import{_ as i,o as e,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2020-05-13:: Ceph DocUBetter Meeting","description":"","frontmatter":{"title":"2020-05-13:: Ceph DocUBetter Meeting","date":"2020-05-13T00:00:00.000Z","updated":"2020-05-14T00:00:00.000Z","tags":["Ceph","分布式存储","文档编写","会议纪要","社区发展"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-05-13_-_-_Ceph_DocUBetter_Meeting.md","filePath":"posts/2020/2020-05-13_-_-_Ceph_DocUBetter_Meeting.md","lastUpdated":1780459816000}'),o={name:"posts/2020/2020-05-13_-_-_Ceph_DocUBetter_Meeting.md"};function r(n,l,s,u,h,p){return e(),t("div",null,[...l[0]||(l[0]=[a('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>会议纪要</p><h3 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h3><ul><li><strong>时间</strong>: 2020年5月13日</li><li><strong>地点</strong>: 线上会议</li><li><strong>参会人员</strong>: 主要参会人员未列出</li><li><strong>主持人</strong>: 未列出</li></ul><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>Google Season of Docs 申请结果</strong></p><ul><li>申请未能成功，原因可能是因为项目过于成熟和知名。</li><li>决定继续推进新手引导文档的编写。</li></ul></li><li><p><strong>API查询问题</strong></p><ul><li>Perth超级计算中心的 Lucas Cervini 反映无法使用标准工具查询 API。</li><li>已提交相关 bug，并寻求文档支持或解决方案。</li></ul></li><li><p><strong>CephIO 垃圾评论处理</strong></p><ul><li>每日处理约 25 条垃圾评论，以保持评论质量。</li><li>讨论了评论审核的标准和流程。</li></ul></li><li><p><strong>Seth Vancouver 会议状态</strong></p><ul><li>会议可能被取消，建议联系 Mike Perez 确认。</li></ul></li><li><p><strong>GitHub 通知设置</strong></p><ul><li>讨论了如何设置 GitHub 通知，以便及时响应 pull request 和 bug。</li></ul></li><li><p><strong>Ceph 培训文档编写</strong></p><ul><li>计划编写一个简单的内部使用文档，介绍如何使用实验室进行测试。</li><li>讨论了现有文档的更新和维护。</li></ul></li><li><p><strong>封装定义倡议</strong></p><ul><li>提出一个新倡议，旨在为每个概念提供简洁明了的定义，帮助新手理解。</li><li>讨论了如何在网站和文档中整合这些定义。</li></ul></li><li><p><strong>文档合规性和网站更新</strong></p><ul><li>讨论了文档合规性列表中的未完成项。</li><li>提到了 Lars 正在进行的全新网站建设项目。</li></ul></li><li><p><strong>文档重定向和报告机制</strong></p><ul><li>确认需要将 docs.com 重定向到 readthedocs 版本，并保留报告文档错误的机制。</li></ul></li><li><p><strong>对象存储工具文档 PR</strong></p><ul><li>讨论了 David 即将审查的对象存储工具文档 PR，并准备合并。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>继续推进新手引导文档的编写。</li><li>确认 Seth Vancouver 会议的状态，并更新相关信息。</li><li>设置 GitHub 通知以便及时响应开发活动。</li><li>编写和更新 Ceph 培训文档。</li><li>推进封装定义倡议，简化概念解释。</li><li>重定向 docs.com 到 readthedocs，并保留报告文档错误的机制。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>联系 Mike Perez 确认 Seth Vancouver 会议的状态。</li><li>更新和维护 Ceph 培训文档。</li><li>实施封装定义倡议，开始编写简洁的概念定义。</li><li>完成对象存储工具文档 PR 的审查和合并。</li><li>确认并实施文档重定向和报告机制的更新。</li></ul><h3 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h3><ul><li>会议中提到的具体日期和细节需要进一步确认和跟进。</li><li>所有参会人员应关注 GitHub 通知，以便及时响应开发活动。</li></ul><h3 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h3><ul><li>预定于后续日期进行，具体时间和议程待定。</li></ul><p>会议讨论了多个重要议题，包括文档编写、API查询问题、Ceph 社区发展等，并制定了相应的行动计划。会议纪要中未包含参会人员名单和主持人姓名，建议在未来的会议中补充这些信息。</p>',15)])])}const _=i(o,[["render",r]]);export{d as __pageData,_ as default};
